// ═══════════════════════════════════════════════════════════════════════════
// font-ro-embed.js — Font Unicode cu diacritice romanesti (DejaVu Sans subset),
// pentru documentele strategice (Masterplan, PMUD) care necesita diacritice reale
// la nivel profesional. Inregistrat per-instanta jsPDF prin window._registerROFont(pdf).
// Subset: Latin + Latin Extended-A/B (a-caciula, a-circumflex, i-circumflex, s/t-virgula) + punctuatie.
// ═══════════════════════════════════════════════════════════════════════════
window._UrbanXRO = { reg: "", bold: "" };
window._registerROFont = function (pdf) {
  try {
    var f = window._UrbanXRO; if (!f || !pdf) return false;
    pdf.addFileToVFS('DejaVuRO.ttf', f.reg); pdf.addFont('DejaVuRO.ttf', 'DejaVuRO', 'normal');
    pdf.addFileToVFS('DejaVuRO-Bold.ttf', f.bold); pdf.addFont('DejaVuRO-Bold.ttf', 'DejaVuRO', 'bold');
    pdf.addFont('DejaVuRO.ttf', 'DejaVuRO', 'italic'); // italic -> regular (pastreaza diacriticele)
    pdf.__unicodeFont = true; // semnal pt pdf-font-ro.js sa NU mai translitereze
    return true;
  } catch (e) { console.warn('[ROFont] register esuat', e); return false; }
};
console.log('[ROFont] font diacritice incarcat');
